# name: ending_alternation_equal_switch
# description: Among pairs with equal numbers of switches where exactly one sequence ends with a switch (last two flips differ), the rate of choosing the sequence that ends with a switch; observed above null means people weigh the ending (recency, avoiding a terminal repeat) more than the model, which is blind to switch position, below means the reverse.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    seqs = pd.unique(pd.concat([a, b]))
    nsw = {s: sum(x != y for x, y in zip(s, s[1:])) for s in seqs}
    ea = (a.str[-1] != a.str[-2]).astype(int)
    eb = (b.str[-1] != b.str[-2]).astype(int)
    m = (a.map(nsw) == b.map(nsw)) & (ea != eb) & (a.str.len() >= 3)
    if m.sum() == 0:
        return 0.5
    ch = np.where(ea[m] == 1, df["chose_left"][m], 1 - df["chose_left"][m])
    return float(np.mean(ch))

# name: run_length_variety_equal_switch
# description: Among pairs with equal numbers of switches whose sequences differ in the number of distinct run lengths, the rate of choosing the sequence with more distinct run lengths (mixed 1s, 2s, 3s); observed above null means people prize irregular run lengths more than the model predicts (it under-produces this choice), below means less.
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    def runs(s):
        out, c = [], 1
        for x, y in zip(s, s[1:]):
            if x == y:
                c += 1
            else:
                out.append(c); c = 1
        out.append(c)
        return out
    nsw = {s: len(runs(s)) for s in seqs}
    var = {s: len(set(runs(s))) for s in seqs}
    a = df["sequence_a"]; b = df["sequence_b"]
    dv = a.map(var) - b.map(var)
    m = (a.map(nsw) == b.map(nsw)) & (dv != 0)
    if m.sum() == 0:
        return 0.5
    ch = np.where(dv[m] > 0, df["chose_left"][m], 1 - df["chose_left"][m])
    return float(np.mean(ch))

# name: model_blind_pair_polarization
# description: Among unordered pairs whose two sequences tie on the model cues (equal tally span share, equal switch count, equal three-flip chunk variety, equal rule-built status), the n-weighted mean squared deviation from 0.5 of the rate of choosing the alphabetically-first sequence; observed above null means people consistently discriminate pairs the model treats as equivalent (a missing cue), below means less.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    seqs = pd.unique(pd.concat([a, b]))
    def span(s):
        t = np.cumsum([1 if c == "H" else -1 for c in s])
        return round((max(t.max(), 0) - min(t.min(), 0)) / len(s), 9)
    def trip(s):
        n = len(s) - 2
        return 0.0 if n < 1 else round(len({s[i:i+3] for i in range(n)}) / min(8, n), 9)
    def rule(s):
        n = len(s)
        if len(set(s)) < 2:
            return 0
        for p in range(2, n // 2 + 1):
            if all(s[i] == s[i+p] for i in range(n - p)):
                return 1
        return int(s == s.translate(str.maketrans("HT", "TH"))[::-1])
    sig = {s: (span(s), sum(x != y for x, y in zip(s, s[1:])), trip(s), rule(s)) for s in seqs}
    m = (a.map(sig) == b.map(sig)) & (a != b)
    if m.sum() == 0:
        return 0.0
    aa = a[m]; bb = b[m]
    first = aa < bb
    key = pd.Series(np.where(first, aa + "|" + bb, bb + "|" + aa), index=aa.index)
    y = pd.Series(np.where(first, df["chose_left"][m], 1 - df["chose_left"][m]), index=aa.index)
    g = y.groupby(key).agg(["mean", "size"])
    return float(np.average((g["mean"] - 0.5) ** 2, weights=g["size"]))

# name: switch_vs_balance_conflict
# description: Among pairs where one sequence has more switches but also a larger heads-tails count imbalance (cues conflict), the rate of choosing the higher-switch sequence; observed above null means people let switching override count balance more than the model predicts, below means count balance dominates more than the model allows.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    seqs = pd.unique(pd.concat([a, b]))
    nsw = {s: sum(x != y for x, y in zip(s, s[1:])) for s in seqs}
    imb = {s: abs(2 * s.count("H") - len(s)) for s in seqs}
    ds = a.map(nsw) - b.map(nsw)
    di = a.map(imb) - b.map(imb)
    m = (ds * di) > 0
    if m.sum() == 0:
        return 0.5
    ch = np.where(ds[m] > 0, df["chose_left"][m], 1 - df["chose_left"][m])
    return float(np.mean(ch))

# name: interior_longest_run_choice
# description: Among pairs with equal switch counts and equal longest-run length where exactly one sequence has a longest run touching an end (first or last flip), the rate of choosing the sequence whose longest run is interior; observed above null means people find edge streaks less random than the model (blind to streak position) predicts, below means interior streaks look less random.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    seqs = pd.unique(pd.concat([a, b]))
    def info(s):
        bounds, start = [], 0
        for i in range(1, len(s) + 1):
            if i == len(s) or s[i] != s[i - 1]:
                bounds.append((start, i)); start = i
        L = max(e - st for st, e in bounds)
        edge = any((e - st) == L and (st == 0 or e == len(s)) for st, e in bounds)
        return (len(bounds), L, int(edge))
    inf = {s: info(s) for s in seqs}
    na = a.map(lambda s: inf[s][0]); nb = b.map(lambda s: inf[s][0])
    la = a.map(lambda s: inf[s][1]); lb = b.map(lambda s: inf[s][1])
    ea = a.map(lambda s: inf[s][2]); eb = b.map(lambda s: inf[s][2])
    m = (na == nb) & (la == lb) & (ea != eb)
    if m.sum() == 0:
        return 0.5
    ch = np.where(ea[m] == 0, df["chose_left"][m], 1 - df["chose_left"][m])
    return float(np.mean(ch))

# name: anti_alternator_share
# description: Share of participants who choose the higher-switch sequence on fewer than 40% of pairs differing in switch rate by >= 0.25; observed above null means a distinct subgroup prefers streaky sequences more than the model's population of ideal switching rates produces, below means the model over-produces such people.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    seqs = pd.unique(pd.concat([a, b]))
    sw = {s: sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1) for s in seqs}
    d = a.map(sw) - b.map(sw)
    m = d.abs() >= 0.25
    ch = pd.Series(np.where(d[m] > 0, df["chose_left"][m], 1 - df["chose_left"][m]), index=d[m].index)
    per = ch.groupby(df["participant_id"][m]).mean()
    if len(per) == 0:
        return 0.0
    return float((per < 0.4).mean())
